import sys

def max_permutation_value(n):
    if n == 1:
        return 0
    if n % 2 == 0:
        return n * (n // 2)
    else:
        return (n - 1) * ((n - 1) // 2) + n

input = sys.stdin.read().split()
t = int(input[0])
results = []
index = 1
for _ in range(t):
    n = int(input[index])
    results.append(str(max_permutation_value(n)))
    index += 1
print("\n".join(results))
